using System;using System.Collections;using System.Collections.Generic;using UnityEngine;using UnityEngine.UI;using IdleIntelligence.Core;
namespace IdleIntelligence.Runtime {
 public sealed class RewardVisual {
  public ItemInstance Item;public Sprite Sprite;public string Label,Name="";public Color Tint=GameTheme.Accent;public RectTransform Target;
 }
 // One shared, bounded and reusable presentation. Receipts contain no grant callback.
 public sealed class RewardStage:MonoBehaviour {
  public HingedChestRig Chest;public Vector3? Origin;public float Elapsed{get;private set;}public RectTransform Stage;public Image Shade;public Text Heading;public Button ShortenButton,CloseButton;public Image Body,Lid,Crank,Door,Capsule;public ItemPortrait Portrait;public Transform Rewards;
  readonly List<Image> balls=new List<Image>();readonly List<Image> icons=new List<Image>();readonly List<Text> labels=new List<Text>();Coroutine running;GameRuntime game;PresentationArt art;bool shorten;string route;public bool IsAnimating=>running!=null;public string ReceiptKey{get;private set;}public int RewardCount{get;private set;}
  public void Initialize(GameRuntime runtime){game=runtime;art=Resources.Load<PresentationArt>("PixelUI/PresentationArt");ShortenButton.onClick.AddListener(()=>shorten=true);CloseButton.onClick.AddListener(Cancel);}
  public void Cancel(){if(running!=null)StopCoroutine(running);running=null;gameObject.SetActive(false);}
  void OnDisable(){if(running!=null)StopCoroutine(running);running=null;}
  public void Present(string key,string kind,int tier,List<RewardVisual> rewards){Cancel();ReceiptKey=key;RewardCount=rewards.Count;shorten=false;route=game.CurrentTab;gameObject.SetActive(true);Heading.text=UiLocalizedText.Translate(kind=="capsule"?"Gumball":kind=="chest"?"Truhe geöffnet":"Kauf abgeschlossen",game.State.Settings.language);ShortenButton.GetComponentInChildren<Text>().text=UiLocalizedText.Translate("Kürzen",game.State.Settings.language);CloseButton.GetComponentInChildren<Text>().text="×";while(icons.Count<rewards.Count){var i=WorkshopUIFactory.Node("ReceiptIcon"+icons.Count,Rewards,typeof(Image)).GetComponent<Image>();i.raycastTarget=false;i.preserveAspect=true;icons.Add(i);var l=WorkshopUIFactory.Label("ReceiptAmount"+labels.Count,Rewards,"",13);Destroy(l.GetComponent<LayoutElement>());l.alignment=TextAnchor.MiddleCenter;labels.Add(l);}
   for(int i=0;i<icons.Count;i++){icons[i].gameObject.SetActive(i<rewards.Count);labels[i].gameObject.SetActive(i<rewards.Count);}ShortenButton.GetComponent<RectTransform>().anchoredPosition=new Vector2(0,kind=="chest"?-252:-192);Chest.Assembly.gameObject.SetActive(kind=="chest");Portrait.gameObject.SetActive(false);Body.gameObject.SetActive(kind!="purchase");Lid.gameObject.SetActive(kind=="chest");Crank.gameObject.SetActive(kind=="capsule");Door.gameObject.SetActive(kind=="capsule");Capsule.gameObject.SetActive(kind=="capsule");
   if(kind=="chest"){Body.transform.SetParent(Chest.Assembly,false);Body.transform.SetAsLastSibling();Chest.Prepare(art,tier);}else{Body.transform.SetParent(Stage,false);Body.transform.SetSiblingIndex(0);}
   if(kind=="capsule"){Body.sprite=art.Machine;Body.rectTransform.sizeDelta=new Vector2(192,288);Body.rectTransform.anchoredPosition=new Vector2(0,20);Crank.sprite=art.Crank;Crank.rectTransform.anchoredPosition=new Vector2(0,-23);Crank.rectTransform.sizeDelta=Vector2.one*55;Door.sprite=art.Door;Door.rectTransform.anchoredPosition=new Vector2(0,-70);Door.rectTransform.sizeDelta=new Vector2(55,44);Capsule.sprite=art.Capsule;Capsule.rectTransform.sizeDelta=Vector2.one*54;Capsule.rectTransform.anchoredPosition=new Vector2(0,-4);while(balls.Count<5){var ball=WorkshopUIFactory.Node("MovingCapsule"+balls.Count,Body.transform,typeof(Image)).GetComponent<Image>();ball.sprite=art.Capsule;ball.raycastTarget=false;ball.preserveAspect=true;ball.rectTransform.anchorMin=ball.rectTransform.anchorMax=Vector2.one*.5f;ball.rectTransform.sizeDelta=Vector2.one*27;balls.Add(ball);}}
   foreach(var b in balls)b.gameObject.SetActive(kind=="capsule");Body.color=Lid.color=Color.white;Lid.rectTransform.localEulerAngles=Vector3.zero;Crank.rectTransform.localEulerAngles=Vector3.zero;Door.rectTransform.localScale=Vector3.one;foreach(var i in icons)i.canvasRenderer.SetAlpha(0);foreach(var l in labels)l.canvasRenderer.SetAlpha(0);
   bool reduced=game.State.Workshop.reducedMotion||!game.State.Settings.effects;running=StartCoroutine(Animate(kind,rewards,reduced));
  }
  IEnumerator Animate(string kind,List<RewardVisual> rewards,bool reduced){float elapsed=0,skipped=0;double began=ReceiptMotion.Now;bool sounded=false;bool cranked=false;float reveal=kind=="purchase"?.1f:kind=="capsule"?1.25f:.88f;float finish=reveal+.8f+Mathf.Min(.4f,rewards.Count*.055f);while(elapsed<finish+.42f){if(route!=game.CurrentTab){Cancel();yield break;}elapsed=ReceiptMotion.Age(began)+skipped;if(reduced)elapsed=Mathf.Max(elapsed,reveal+.55f);if(shorten&&elapsed<finish){skipped+=finish-elapsed;elapsed=finish;}Elapsed=elapsed;float t=elapsed;if(kind=="capsule"&&!cranked){cranked=true;game.Audio?.Play("gumball-turn");}Heading.canvasRenderer.SetAlpha(1-ReceiptMotion.Ease((t-finish)/.42f));ShortenButton.gameObject.SetActive(t<finish);CloseButton.gameObject.SetActive(t<finish);Shade.color=new Color(.01f,.025f,.045f,(kind=="purchase"?.92f:kind=="chest"?.995f:.97f)*(1-ReceiptMotion.Ease((t-finish)/.42f)));
    if(kind=="chest"){float prepare=reduced?0:Mathf.Sin(Mathf.Clamp01(t/.55f)*Mathf.PI);float open=ReceiptMotion.Ease((t-.43f)/.42f);Chest.Pose(open,prepare,ReceiptMotion.Ease((t-reveal)/.42f));}
    if(kind=="capsule"){Crank.rectTransform.localEulerAngles=new Vector3(0,0,-360*ReceiptMotion.Ease(t/.55f));float door=ReceiptMotion.Ease((t-.48f)/.15f);Door.rectTransform.localScale=new Vector3(1,1-door*.86f,1);for(int j=0;j<balls.Count;j++){float a=j*2.399f+t*8;balls[j].rectTransform.anchoredPosition=new Vector2(Mathf.Cos(a)*50,52+Mathf.Sin(a)*33)*(t<.65f?1:0);balls[j].gameObject.SetActive(t<.75f);}float drop=Mathf.Clamp01((t-.55f)/.48f);Capsule.rectTransform.anchoredPosition=ReceiptMotion.Arc(new Vector2(0,-4),new Vector2(0,-93),drop*drop,24)+Vector2.up*(t>.98f?Mathf.Sin(Mathf.Clamp01((t-.98f)/.25f)*Mathf.PI)*8:0);Capsule.sprite=t<1.21f?art.Capsule:art.OpenCapsule;Capsule.color=new Color(1,1,1,t>=.55f?1:0);}
    if(t>=reveal&&!sounded){sounded=true;game.Audio?.Play(kind=="purchase"?"purchase-confirm":kind=="capsule"?"gumball-open":"research-complete");if(!reduced)PixelImpact.Play(Stage,"ReceiptImpact",new Vector2(0,30),kind=="purchase"?70:140,GameTheme.Gold,.24f);}
    float retire=ReceiptMotion.Ease((t-reveal)/.24f);if(kind=="chest")Chest.SetOpacity(1-ReceiptMotion.Ease((t-finish)/.42f));else Body.color=Lid.color=new Color(1,1,1,1-retire);Crank.color=Door.color=Capsule.color=new Color(1,1,1,1-retire);
    int itemIndex=rewards.FindIndex(r=>r.Item!=null);for(int j=0;j<rewards.Count;j++){var reward=rewards[j];float enter=ReceiptMotion.Out((t-reveal-j*.055f)/.22f);int resources=rewards.Count-(itemIndex>=0?1:0);int index=j-(itemIndex>=0&&j>itemIndex?1:0);float width=Mathf.Min(300,Stage.rect.width-24);int columns=Mathf.Min(5,resources);Vector2 resting=reward.Item!=null?new Vector2(0,65):new Vector2((index%columns-(columns-1)*.5f)*width/columns,(itemIndex>=0?-100:35)-(index/columns)*55);var icon=icons[j];var label=labels[j];icon.sprite=reward.Sprite;icon.rectTransform.anchorMin=icon.rectTransform.anchorMax=Vector2.one*.5f;icon.rectTransform.sizeDelta=Vector2.one*(rewards.Count==1?(kind=="purchase"?64:88):resources>5?32:42);label.rectTransform.anchorMin=label.rectTransform.anchorMax=Vector2.one*.5f;label.rectTransform.sizeDelta=new Vector2(reward.Item!=null||rewards.Count==1?290:width/Mathf.Max(1,columns)-4,reward.Item!=null?42:32);label.text=reward.Label+(rewards.Count==1&&reward.Name!=""?" "+reward.Name:"");label.color=reward.Item!=null?GameTheme.Text:reward.Tint;label.resizeTextForBestFit=true;label.resizeTextMinSize=11;label.resizeTextMaxSize=rewards.Count==1?18:13;label.fontSize=label.resizeTextMaxSize;Vector2 pos=kind=="purchase"&&Origin.HasValue?ReceiptMotion.Arc(Stage.InverseTransformPoint(Origin.Value),resting,enter,30):resting+Vector2.down*(1-enter)*22;if(kind=="chest"){resting=reward.Item!=null?new Vector2(0,80):new Vector2((index%columns-(columns-1)*.5f)*width/columns,(itemIndex>=0?-38:60)-(index/columns)*50);pos=reduced?resting:ReceiptMotion.Arc(Stage.InverseTransformPoint(Chest.Mouth),resting,enter,38);label.rectTransform.sizeDelta=new Vector2(label.rectTransform.sizeDelta.x,reward.Item!=null?42:22);}float transfer=reduced?0:ReceiptMotion.Ease((t-finish)/.42f);if(transfer>0&&reward.Target!=null)pos=ReceiptMotion.Arc(resting,Stage.InverseTransformPoint(reward.Target.position),transfer,32);icon.rectTransform.anchoredPosition=pos;label.rectTransform.anchoredPosition=resting+Vector2.down*(reward.Item!=null?104:rewards.Count==1?68:kind=="chest"?28:34);icon.canvasRenderer.SetAlpha(reward.Item!=null?0:enter*(1-transfer*.65f));label.canvasRenderer.SetAlpha(enter*(1-transfer));if(reward.Item!=null&&enter>0){if(!Portrait.gameObject.activeSelf){Portrait.ShowLevel=false;Portrait.Bind(reward.Item);Portrait.gameObject.SetActive(true);}var pr=(RectTransform)Portrait.transform;pr.anchoredPosition=pos;pr.sizeDelta=Vector2.one*Mathf.Lerp(kind=="chest"?148:164,42,transfer);pr.localScale=Vector3.one*(.8f+.2f*enter)*ReceiptMotion.Settle(enter);Portrait.Frame.Reveal=enter;Portrait.Frame.SetVerticesDirty();Portrait.Art.canvasRenderer.SetAlpha(enter);}}
    if(reduced){running=null;yield break;}yield return null;
   }
   foreach(var r in rewards)if(r.Target!=null)PixelImpact.Play(r.Target,"ReceivedReward",Vector2.zero,42,r.Tint,.15f);running=null;gameObject.SetActive(false);
  }
 }
